124	/// The run grade: signals are facts about the run's batch series,
125	/// `letter` is the worst signal's grade.
126	#[derive(Debug)]
127	pub struct RunGrade {
128	    /// Samples above their batch's over-floor cut, as a fraction
129	    /// of all samples in the run.
130	    pub interference_frac: f64,
131	    /// Fraction of batches whose mean is [`BURST_TOL`] above the
132	    /// run's median batch mean.
133	    pub burst_frac: f64,
134	    /// End to end: median batch floor of the run's last quarter
135	    /// against its first, relative.
136	    pub drift_frac: f64,
137	    /// The largest floor shift any split of the run divides,
138	    /// relative — median floor before against median floor after.
139	    pub step_frac: f64,
140	    /// Where that split fell — seconds from run start.
141	    pub step_at_s: f64,
142	    /// Overall letter, worst signal wins: A, B, C, D, or F.
143	    pub letter: char,
144	}
