146	impl RunGrade {
147	    /// Grade a run from its time-ordered batch summaries; `None`
148	    /// when the run produced no batches (nothing to grade).
149	    ///
150	    /// - Both floor signals read `floor_q_ps`, the batch's robust
151	    ///   low-quantile floor, never its raw min — see
152	    ///   [`crate::harness::BATCH_FLOOR_Q`] for the measurement
153	    ///   that settled it.
154	    /// - `drift` compares the median floor of the run's first
155	    ///   quarter against its last: the plain end-to-end question,
156	    ///   did the run finish where it started. Movement is
157	    ///   reported, not attributed — see the module doc.
158	    /// - `step` is the transition detector — the split point that
159	    ///   most divides the floor series, scored on the medians of
160	    ///   the two sides. A run that shifts and shifts back reads
161	    ///   low on drift and high on step; the reported time says
162	    ///   when it happened.
163	    /// - Both are medians, not extremes, on purpose: a single hot
164	    ///   batch is a burst, not a transition, and an adjacent-pair
165	    ///   detector graded every quiet 3900X run D/F on exactly
166	    ///   those isolated batches.
167	    /// - Runs shorter than [`MIN_SPLIT_BATCHES`] batches per side
168	    ///   score 0 on both — too few floors to say anything.
169	    pub fn from_batches(batches: &[BatchSummary]) -> Option<Self> {
170	        if batches.is_empty() {
171	            return None;
172	        }
173	
174	        let total: u64 = batches.iter().map(|b| b.count).sum();
175	        let over: u64 = batches.iter().map(|b| b.over_floor).sum();
176	        let interference_frac = if total == 0 {
177	            0.0
178	        } else {
179	            over as f64 / total as f64
180	        };
181	
182	        let means: Vec<f64> = batches.iter().map(|b| b.mean_ps).collect();
183	        let typical = median(&means).unwrap_or(0.0); // OK: `batches` is non-empty
184	        let hot = means
185	            .iter()
186	            .filter(|&&m| m > typical * (1.0 + BURST_TOL))
187	            .count();
188	        let burst_frac = hot as f64 / batches.len() as f64;
189	
190	        let floors: Vec<f64> = batches.iter().map(|b| b.floor_q_ps as f64).collect();
191	        let n = floors.len();
192	
193	        let quarter = (n / 4).max(1);
194	        let drift_frac = split_change(&floors[..quarter], &floors[n - quarter..]);
195	
196	        // Every interior split point, keeping MIN_SPLIT_BATCHES on
197	        // each side. n is the batch count (~20/s), so the O(n^2 log
198	        // n) scan costs microseconds against a run's seconds.
199	        //
200	        // Ranked by change x the split's balance, `n1 * n2 / n^2`:
201	        // a run's floor series has a plateau of splits reading the
202	        // same change (any cut inside the earlier level sees the
203	        // same two medians), and the balance term picks the one
204	        // nearest the middle of that plateau — the transition
205	        // itself — instead of whichever tie came first.
206	        let mut step_frac = 0.0f64;
207	        let mut step_at_s = batches[0].t_start_s;
208	        let mut best_rank = 0.0f64;
209	        if n >= 2 * MIN_SPLIT_BATCHES {
210	            for t in MIN_SPLIT_BATCHES..=(n - MIN_SPLIT_BATCHES) {
211	                let change = split_change(&floors[..t], &floors[t..]);
212	                let balance = (t * (n - t)) as f64 / (n * n) as f64;
213	                let rank = change * balance;
214	                if rank > best_rank {
215	                    best_rank = rank;
216	                    step_frac = change;
217	                    step_at_s = batches[t].t_start_s;
218	                }
219	            }
220	        }
221	
222	        let mut grade = Self {
223	            interference_frac,
224	            burst_frac,
225	            drift_frac,
226	            step_frac,
227	            step_at_s,
228	            letter: 'A',
229	        };
230	        grade.letter = score_letter(grade.scores().into_iter().fold(0, u8::max));
231	        Some(grade)
232	    }
233	
234	    /// Per-signal scores in print order: interference, bursts,
235	    /// drift, step.
236	    ///
237	    /// Each is the count of its [`thresholds`] cutoffs crossed —
238	    /// 0 (below all four) through 4 — and the composite is
239	    /// `fold(0, u8::max)` over them: the worst signal wins
240	    /// outright, so one F makes the letter F and no number of
241	    /// A's pulls it back. Printing every signal's letter beside
242	    /// the composite makes that visible: the overall letter is
243	    /// always one of the four shown.
244	    fn scores(&self) -> [u8; 4] {
245	        [
246	            score(self.interference_frac, thresholds::INTERFERENCE),
247	            score(self.burst_frac, thresholds::BURSTS),
248	            score(self.drift_frac, thresholds::DRIFT),
249	            score(self.step_frac, thresholds::STEP),
250	        ]
251	    }
252	
253	    /// Letters for the gauge line's printed signals, in print
254	    /// order — all four composite inputs, so the worst letter on
255	    /// the line *is* the composite.
256	    pub fn signal_letters(&self) -> [char; 4] {
257	        self.scores().map(score_letter)
258	    }
259	}
260	
261	/// Relative change between two runs of floors, each summarized by
262	/// its median: `|median(b) - median(a)| / median(a)`. Zero when
263	/// either side is empty or the earlier median is not positive.
264	fn split_change(a: &[f64], b: &[f64]) -> f64 {
265	    match (median(a), median(b)) {
266	        (Some(early), Some(late)) if early > 0.0 => (late - early).abs() / early,
267	        _ => 0.0,
268	    }
269	}
270	
271	/// Median of a slice, `None` when empty. Copies to sort — the
272	/// slices are batch counts, not sample counts.
273	fn median(v: &[f64]) -> Option<f64> {
274	    if v.is_empty() {
275	        return None;
276	    }
277	    let mut s = v.to_vec();
278	    s.sort_by(f64::total_cmp);
279	    Some(s[s.len() / 2])
280	}
281	
282	#[cfg(test)]
283	mod tests {
284	    use super::*;
285	
286	    /// One batch with the given floor / mean / census counts,
287	    /// stamped at `at` seconds and 50 ms long.
288	    fn batch_at(at: f64, floor_ps: u64, mean_ps: f64, count: u64, over_floor: u64) -> BatchSummary {
289	        BatchSummary {
290	            t_start_s: at,
291	            t_end_s: at + 0.05,
292	            count,
293	            floor_ps,
294	            floor_q_ps: floor_ps,
295	            mean_ps,
296	            max_ps: floor_ps * 2,
297	            over_floor,
298	        }
299	    }
300	
301	    /// A run of `n` identical batches, one every 50 ms.
302	    fn steady(n: usize, floor_ps: u64, mean_ps: f64, over_floor: u64) -> Vec<BatchSummary> {
303	        (0..n)
304	            .map(|i| batch_at(i as f64 * 0.05, floor_ps, mean_ps, 1000, over_floor))
305	            .collect()
306	    }
307	
308	    #[test]
309	    fn empty_run_has_no_grade() {
310	        assert!(RunGrade::from_batches(&[]).is_none());
311	    }
312	
313	    #[test]
314	    fn quiet_run_grades_a() {
315	        let g = RunGrade::from_batches(&steady(8, 1000, 1010.0, 2)).expect("graded");
316	        assert_eq!(g.letter, 'A');
317	        assert_eq!(g.signal_letters(), ['A', 'A', 'A', 'A']);
318	    }
319	
320	    #[test]
321	    fn single_batch_cannot_move() {
322	        let g = RunGrade::from_batches(&steady(1, 1000, 1010.0, 0)).expect("graded");
323	        assert_eq!(g.drift_frac, 0.0);
324	        assert_eq!(g.step_frac, 0.0);
325	    }
326	
327	    /// A run whose floor follows `segments` — `(batches, floor)`
328	    /// each, one batch every 50 ms from t=0.
329	    fn run_of(segments: &[(usize, u64)]) -> Vec<BatchSummary> {
330	        let mut out = Vec::new();
331	        for &(n, floor) in segments {
332	            for _ in 0..n {
333	                let at = out.len() as f64 * 0.05;
334	                out.push(batch_at(at, floor, floor as f64 + 10.0, 1000, 0));
335	            }
336	        }
337	        out
338	    }
339	
340	    #[test]
341	    fn floor_shift_lights_drift_and_step() {
342	        // Halves at 1000 / 1200 ps: 20% end to end, and the split
343	        // at the seam finds the same 20%, at t = 8 x 50 ms.
344	        let g = RunGrade::from_batches(&run_of(&[(8, 1000), (8, 1200)])).expect("graded");
345	        assert!((g.drift_frac - 0.2).abs() < 1e-9);
346	        assert!((g.step_frac - 0.2).abs() < 1e-9);
347	        assert!((g.step_at_s - 0.4).abs() < 1e-9);
348	        assert_eq!(g.letter, 'F');
349	        assert_eq!(g.signal_letters(), ['A', 'A', 'F', 'F']);
350	    }
351	
352	    #[test]
353	    fn returning_shift_hides_from_drift_only() {
354	        // Out and back: the run ends where it started, so drift
355	        // sees nothing and the split detector sees the departure.
356	        let g =
357	            RunGrade::from_batches(&run_of(&[(6, 1000), (8, 1200), (6, 1000)])).expect("graded");
358	        assert_eq!(g.drift_frac, 0.0);
359	        assert!((g.step_frac - 0.2).abs() < 1e-9);
360	        // No assertion on `step_at_s`: two transitions have no one
361	        // split point, and the balance term lands it between them.
362	    }
363	
364	    #[test]
365	    fn transient_batch_is_not_a_transition() {
366	        // One hot batch in twenty: a burst, not a state change —
367	        // the medians on both sides of every split are unmoved.
368	        // (The adjacent-pair detector this replaced read 20%.)
369	        let g =
370	            RunGrade::from_batches(&run_of(&[(10, 1000), (1, 1200), (9, 1000)])).expect("graded");
371	        assert_eq!(g.drift_frac, 0.0);
372	        assert_eq!(g.step_frac, 0.0);
373	        assert_eq!(g.letter, 'A');
374	    }
375	
376	    #[test]
377	    fn census_counts_drive_interference() {
378	        let mut batches = steady(2, 1000, 1010.0, 0);
379	        batches[0].over_floor = 100;
380	        let g = RunGrade::from_batches(&batches).expect("graded");
381	        assert!((g.interference_frac - 0.05).abs() < 1e-9);
382	        assert_eq!(g.signal_letters()[0], 'B');
383	    }
384	
385	    #[test]
386	    fn hot_batches_drive_bursts() {
387	        // Three of ten means sit > 5% above the median batch.
388	        let mut batches = steady(10, 1000, 1000.0, 0);
389	        for b in batches.iter_mut().take(3) {
390	            b.mean_ps = 1200.0;
391	        }
392	        let g = RunGrade::from_batches(&batches).expect("graded");
393	        assert!((g.burst_frac - 0.3).abs() < 1e-9);
394	        assert_eq!(g.signal_letters()[1], 'B');
395	    }
396	
397	    #[test]
398	    fn a_broad_bench_is_not_bursty() {
399	        // Batch means scattered ±4% around the median: spread,
400	        // not bursts. Against the *quietest* batch this read 100%.
401	        let mut batches = steady(10, 1000, 1000.0, 0);
402	        for (i, b) in batches.iter_mut().enumerate() {
403	            b.mean_ps = if i % 2 == 0 { 1000.0 } else { 1040.0 };
404	        }
405	        let g = RunGrade::from_batches(&batches).expect("graded");
406	        assert_eq!(g.burst_frac, 0.0);
