/// intervals) and summarize the per-pair distribution.
///
/// - `since` anchors [`ProbeSummary::t_start_s`]; pass the warmup
///   start so a series shares one time origin.
/// - The floor is a low quantile, not the minimum: it rejects
///   one-sided interference (preemption only ever inflates a
///   group) while staying off the exact edge.
fn micro_probe(since: std::time::Instant) -> ProbeSummary {
    let t_start_s = since.elapsed().as_nanos() as f64 / 1e9;
    let mut groups: Vec<u64> = Vec::with_capacity(MICRO_PROBE_GROUPS);
    for _ in 0..MICRO_PROBE_GROUPS {
        let group_start = std::time::Instant::now();
        for _ in 0..MICRO_PROBE_GROUP {
            let start = std::time::Instant::now();
            black_box(start.elapsed());
        }
        let total_ns = group_start.elapsed().as_nanos() as f64;
        groups.push((total_ns * PS_PER_NS / MICRO_PROBE_GROUP as f64) as u64);
    }
    groups.sort_unstable();

    let floor_q_ps = quantile_at(&groups, ENV_FLOOR_Q).max(1);
    let spread_q_ps = quantile_at(&groups, ENV_SPREAD_Q);
    let sum: u128 = groups.iter().map(|&g| u128::from(g)).sum();
    let mean_ps = sum as f64 / groups.len() as f64;
    let cut = over_floor_cut(floor_q_ps, ENV_OVER_ADD_PS);
    let over_floor = groups.iter().filter(|&&g| g > cut).count() as u64;

    ProbeSummary {
        t_start_s,
        count: groups.len() as u64,
        floor_q_ps,
        spread_q_ps,
        mean_ps,
        over_floor,
    }
}

/// Value at quantile `q` of an already-sorted slice, clamped to
/// the last element. Empty input yields 0.
fn quantile_at(sorted: &[u64], q: f64) -> u64 {
    if sorted.is_empty() {
        return 0;
    }
    let idx = ((sorted.len() as f64 * q) as usize).min(sorted.len() - 1);
    sorted[idx]
}

/// Census cut for a floor: `max(BATCH_OVER_MULT x floor, floor + add)`
/// — the multiplicative rule with an additive guard so a very
/// small floor doesn't make every sample "over".
fn over_floor_cut(floor_ps: u64, add_ps: u64) -> u64 {
    ((floor_ps as f64 * BATCH_OVER_MULT) as u64).max(floor_ps + add_ps)
}

/// Warm the bench and measure the box at the same time: run the
/// [`WARMUP`] steps in [`ENV_PROBES`] chunks with a micro-probe
/// after each, returning the probe series.
///
/// - The probes interleave with warmup rather than preceding it,
///   so the series spans the window where a frequency governor
///   ramps — the movement the environment grade exists to catch —
///   and the *last* probe, the sizing input, is taken after the
///   full warmup, as it was when the probe was a single shot.
/// - Warmup step count is unchanged; the probes add ~16 ms. The
///   "Dynamic startup warmup" Todo replaces the fixed count with
///   warm-until-stable and will consume this series as its
///   convergence input.
fn warmup_and_probe<B: Bench>(bench: &mut B) -> Vec<ProbeSummary> {
    let warm_start = std::time::Instant::now();
    let chunk = (WARMUP / ENV_PROBES as u64).max(1);
    let mut probes = Vec::with_capacity(ENV_PROBES);
    for _ in 0..ENV_PROBES {
        for _ in 0..chunk {
            black_box(bench.step());
        }
        probes.push(micro_probe(warm_start));
    }
    probes
}

