/// One probe with the given floor / upper quantile / census
/// count, stamped at `at` seconds.
fn probe_at(at: f64, floor_ps: u64, spread_q_ps: u64, over_floor: u64) -> ProbeSummary {
    ProbeSummary {
        t_start_s: at,
        count: 512,
        floor_q_ps,
        spread_q_ps,
        mean_ps: floor_ps as f64 + 10.0,
        over_floor,
    }
}

/// A warmup of `n` identical probes, one every millisecond.
fn probes(n: usize, floor_ps: u64, spread_q_ps: u64, over_floor: u64) -> Vec<ProbeSummary> {
    (0..n)
        .map(|i| probe_at(i as f64 * 0.001, floor_ps, spread_q_ps, over_floor))
        .collect()
}

